//! Deterministic Rust source generation from the owned model.

use std::collections::BTreeMap;
use std::fmt::Write as _;
use std::path::Path;

use anyhow::{Context, Result, bail};

use crate::emit::output::{GeneratedFiles, comment_header, ensure_outside_wit_root};
use crate::emit::versions::{DepLayout, Version, load_versions};
use crate::emit::{docs, pascal_case, rust_ident, rustfmt, snake_case};
use crate::model::{Model, TypeDef, TypeDefKind, TypeExpr};

/// Legacy pre-0.6.0 shared ownership header.
///
/// Current output writes a per-generator, per-contract header
/// (`// @generated by witforge (rust, <namespace>:<name>); do not edit.`); files starting with
/// this legacy header are adopted and rewritten on generation.
pub const HEADER: &str = "// @generated by witforge; do not edit.";

pub(crate) fn header_for(namespace: &str, name: &str) -> String {
    comment_header("rust", namespace, name)
}

/// Plan the complete Rust output for a WIT root without writing anything.
///
/// Every `v<major>.<minor>` directory is loaded, checked against the subset, modelled, and
/// checked against its committed v2 lockfile. All versions must share one package namespace and
/// name.
///
/// # Errors
///
/// Returns an error for a missing, duplicate, or symlinked version directory, or an unreadable or
/// invalid lockfile, and a [`crate::ContractError`] for an inconsistent package, subset violations, a
/// stale lockfile, or generated-name collisions.
pub fn plan(wit_root: &Path) -> Result<GeneratedFiles> {
    plan_with_serde(wit_root, false)
}

/// Plan the Rust output for `wit_root`, optionally adding serde derives.
///
/// Serde is opt-in because it changes generated source and requires the consumer to depend on
/// `serde` with the `derive` feature.
///
/// # Errors
///
/// Returns the same errors as [`plan`].
pub fn plan_with_serde(wit_root: &Path, serde: bool) -> Result<GeneratedFiles> {
    plan_versions_with_serde(&load_versions(wit_root)?, serde)
}

/// Plan the Rust output for validated `versions`, which [`load_versions`] returns.
///
/// An emitter error is passed on as the emitter classified it: a contract violation stays a
/// [`crate::ContractError`] and an internal error stays a plain error.
pub(crate) fn plan_versions_with_serde(
    versions: &[Version],
    serde: bool,
) -> Result<GeneratedFiles> {
    let dep_layout = DepLayout::from_versions(versions)?;
    let package = &versions
        .first()
        .context("no version directories found under WIT root")?
        .model
        .package;
    let header = header_for(&package.namespace, &package.name);
    let mut modules = BTreeMap::new();
    let mut files = GeneratedFiles::new(&header);
    let mut module_entries: Vec<(String, String)> = Vec::new();
    for version in versions {
        let module = version_module_name(&version.model);
        if let Some(previous) = modules.insert(module.clone(), &version.directory) {
            contract_bail!(
                "version module `{module}` is produced by both {} and {}",
                previous.display(),
                version.directory.display()
            );
        }
        let major = version.major;
        let resolver = |ns: &str, pkg: &str| -> Result<String> {
            let pkg_mod = rust_ident(
                &format!("{}_{}", snake_case(ns), snake_case(pkg)),
                "dependency package module",
            )?;
            if dep_layout.is_scoped(ns, pkg) {
                Ok(format!("super::super::witforge_deps::v{major}::{pkg_mod}"))
            } else {
                Ok(format!("super::super::witforge_deps::{pkg_mod}"))
            }
        };
        let generated = emit_version_with_resolver(&version.model, serde, &resolver)
            .with_context(|| version.directory.display().to_string())?;
        files.insert(format!("{module}.rs"), generated)?;
        module_entries.push((
            format!("Contract version `{}`.", version.model.package.version),
            format!("pub mod {module};"),
        ));
    }
    if let Some(converted) = super::convert::plan(versions)? {
        files.insert("convert.rs", converted)?;
        module_entries.push((
            "Version-to-version adapters.".to_string(),
            "pub mod convert;".to_string(),
        ));
    }
    if !dep_layout.is_empty() {
        let dependency_source = emit_dependency_bindings_layout(&header, &dep_layout, serde)?;
        files.insert("witforge_deps.rs", dependency_source)?;
        module_entries.push((
            "Pinned dependency types.".to_string(),
            "pub mod witforge_deps;".to_string(),
        ));
    }
    if versions
        .iter()
        .any(|version| !version.model.worlds.is_empty())
    {
        files.insert("worlds.rs", emit_worlds(versions)?)?;
        module_entries.push(("World metadata.".to_string(), "pub mod worlds;".to_string()));
    }
    let mut complete = String::new();
    writeln!(complete, "{header}")?;
    writeln!(
        complete,
        "// source: {}:{}",
        package.namespace, package.name
    )?;
    for (doc, decl) in module_entries {
        // Separating each `pub mod` declaration with a blank line keeps ascending semver order
        // stable under both Rustfmt Edition 2021 and Edition 2024 (including `v0_2` vs `v0_10`).
        writeln!(complete)?;
        writeln!(complete, "/// {doc}")?;
        writeln!(complete, "{decl}")?;
    }
    files.insert("mod.rs", complete)?;
    Ok(files)
}

/// Generate Rust output under `out`.
///
/// # Errors
///
/// Returns an error for invalid input, an output root inside the WIT tree, or an I/O failure.
pub fn generate(wit_root: &Path, out: &Path) -> Result<()> {
    generate_with_serde(wit_root, out, false)
}

/// Generate Rust output under `out`, optionally adding serde derives.
///
/// # Errors
///
/// Returns the same errors as [`generate`].
pub fn generate_with_serde(wit_root: &Path, out: &Path, serde: bool) -> Result<()> {
    ensure_outside_wit_root(wit_root, out)?;
    plan_with_serde(wit_root, serde)?.write(out)
}

/// Check generated Rust output under `out` without writing.
///
/// Returns one message per missing, changed, or extra generated file.
///
/// # Errors
///
/// Returns an error for invalid input, an output root inside the WIT tree, or an I/O failure.
pub fn check(wit_root: &Path, out: &Path) -> Result<Vec<String>> {
    check_with_serde(wit_root, out, false)
}

/// Check Rust output under `out`, optionally expecting serde derives.
///
/// # Errors
///
/// Returns the same errors as [`check`].
pub fn check_with_serde(wit_root: &Path, out: &Path, serde: bool) -> Result<Vec<String>> {
    ensure_outside_wit_root(wit_root, out)?;
    plan_with_serde(wit_root, serde)?.check(out)
}

/// The Rust module name for one contract version: `v<major>_<minor>`.
#[must_use]
pub fn version_module_name(model: &Model) -> String {
    format!(
        "v{}_{}",
        model.package.version.major, model.package.version.minor
    )
}

/// Validate that `model` (root package and pinned dependencies) can be emitted to plain Rust
/// without contract refusals.
pub(crate) fn validate_model(model: &Model) -> Result<()> {
    let _ = emit_version(model)?;
    if !model.dependencies.is_empty() {
        let header = header_for(&model.package.namespace, &model.package.name);
        let _ = emit_dependency_bindings(&header, &model.dependencies, false)?;
    }
    Ok(())
}

/// Emit one version module.
///
/// The result is a complete Rust source file containing one inline module per interface and
/// re-exports of traits for interfaces that declare functions. Worlds produce no code here.
///
/// # Errors
///
/// Returns a [`crate::ContractError`] when a WIT name cannot be represented in Rust or a generated name
/// collides, and a plain error when a named type is missing from the model, which a model built
/// by [`crate::model::build`] never produces.
pub fn emit_version(model: &Model) -> Result<String> {
    emit_version_with_serde(model, false)
}

/// Emit one version module, optionally adding serde derives to generated records, enums,
/// variants, and flags.
///
/// Serde derives require the consumer's `serde` crate with the `derive` feature. Type aliases
/// themselves cannot derive; their target types do.
///
/// # Errors
///
/// Returns the same errors as [`emit_version`].
pub fn emit_version_with_serde(model: &Model, serde: bool) -> Result<String> {
    let resolver = |ns: &str, pkg: &str| -> Result<String> {
        let pkg_mod = rust_ident(
            &format!("{}_{}", snake_case(ns), snake_case(pkg)),
            "dependency package module",
        )?;
        Ok(format!("super::super::witforge_deps::{pkg_mod}"))
    };
    emit_version_with_resolver(model, serde, &resolver)
}

fn emit_version_with_resolver(
    model: &Model,
    serde: bool,
    foreign_resolver: &dyn Fn(&str, &str) -> Result<String>,
) -> Result<String> {
    let mut out = String::new();
    writeln!(
        out,
        "{}",
        header_for(&model.package.namespace, &model.package.name)
    )?;
    writeln!(
        out,
        "// source: {}:{}@{}",
        model.package.namespace, model.package.name, model.package.version
    )?;
    if serde {
        writeln!(
            out,
            "// serde derives require the consumer's `serde` crate with `derive`."
        )?;
    }
    let has_inner_docs = !docs::sanitize_rust_lines(&model.package.docs).is_empty();
    if has_inner_docs {
        writeln!(out)?;
        let _ = docs::write_rust_inner(&mut out, &model.package.docs)?;
    }

    let mut modules = BTreeMap::new();
    let mut traits = BTreeMap::new();
    for interface in &model.interfaces {
        let module = rust_ident(&snake_case(&interface.name), "interface module")?;
        if let Some(previous) = modules.insert(module.clone(), interface.name.clone()) {
            contract_bail!(
                "interface modules `{previous}` and `{}` both map to Rust module `{module}`",
                interface.name
            );
        }
        if !interface.functions.is_empty() {
            let trait_name = rust_ident(&pascal_case(&interface.name), "interface trait")?;
            if let Some(previous) = traits.insert(trait_name.clone(), interface.name.clone()) {
                contract_bail!(
                    "interfaces `{previous}` and `{}` both map to Rust trait `{trait_name}`",
                    interface.name
                );
            }
        }
    }

    let mut root_names: BTreeMap<String, String> = BTreeMap::new();
    for (module, interface) in &modules {
        root_names.insert(module.clone(), format!("module {interface}"));
    }
    for (trait_name, interface) in &traits {
        if let Some(previous) = root_names.insert(trait_name.clone(), format!("trait {interface}"))
        {
            contract_bail!(
                "Rust root name `{trait_name}` is produced by {previous} and trait {interface}"
            );
        }
    }

    let parent_module = version_module_name(model);
    for interface in &model.interfaces {
        let module = rust_ident(&snake_case(&interface.name), "interface module")?;
        writeln!(out)?;
        rustfmt::write_docs_or(
            &mut out,
            0,
            &interface.docs,
            &format!("Interface `{}`.", interface.name),
        )?;
        if module == parent_module {
            writeln!(out, "#[allow(clippy::module_inception)]")?;
        }
        if interface.types.is_empty() && interface.functions.is_empty() {
            writeln!(out, "pub mod {module} {{}}")?;
        } else {
            writeln!(out, "pub mod {module} {{")?;
            emit_interface(&mut out, 4, model, interface, serde, foreign_resolver)?;
            writeln!(out, "}}")?;
        }
    }
    for interface in &model.interfaces {
        if interface.functions.is_empty() {
            continue;
        }
        let module = rust_ident(&snake_case(&interface.name), "interface module")?;
        let trait_name = rust_ident(&pascal_case(&interface.name), "interface trait")?;
        // Separate each re-export with a blank line so Rustfmt Edition 2021 and Edition 2024
        // both keep WIT source order without re-sorting.
        writeln!(out)?;
        writeln!(out, "pub use {module}::{trait_name};")?;
    }
    Ok(out)
}

fn emit_interface(
    out: &mut String,
    indent: usize,
    model: &Model,
    interface: &crate::model::Interface,
    serde: bool,
    foreign_resolver: &dyn Fn(&str, &str) -> Result<String>,
) -> Result<()> {
    let mut type_names: BTreeMap<String, String> = BTreeMap::new();
    let trait_name = if interface.functions.is_empty() {
        None
    } else {
        let name = rust_ident(&pascal_case(&interface.name), "interface trait")?;
        type_names.insert(name.clone(), format!("trait {}", interface.name));
        Some(name)
    };

    for def in &interface.types {
        let name = rust_ident(&pascal_case(&def.name), "type")?;
        insert_name(
            &mut type_names,
            &name,
            &format!("type {}/{}", interface.name, def.name),
            "interface scope",
        )?;
    }
    let mut first = true;
    for def in &interface.types {
        if !first {
            writeln!(out)?;
        }
        first = false;
        emit_type_def(out, indent, model, interface, def, serde, foreign_resolver)?;
    }
    if let Some(trait_name) = trait_name {
        if !first {
            writeln!(out)?;
        }
        emit_trait(out, indent, model, interface, &trait_name, foreign_resolver)?;
    }
    Ok(())
}

fn emit_dependency_bindings(
    header: &str,
    dependencies: &[crate::model::Dependency],
    serde: bool,
) -> Result<String> {
    let mut layout = DepLayout::default();
    for dep in dependencies {
        layout.shared.insert(
            (dep.package.namespace.clone(), dep.package.name.clone()),
            dep.clone(),
        );
    }
    emit_dependency_bindings_layout(header, &layout, serde)
}

#[allow(clippy::too_many_lines)]
fn emit_dependency_bindings_layout(
    header: &str,
    layout: &DepLayout,
    serde: bool,
) -> Result<String> {
    let mut out = String::new();
    writeln!(out, "{header}")?;
    writeln!(out, "// source: wit/deps")?;
    if serde {
        writeln!(
            out,
            "// serde derives require the consumer's `serde` crate with `derive`."
        )?;
    }
    let shared_slice: Vec<crate::model::Dependency> = layout.shared.values().cloned().collect();
    let shared_resolver = |ns: &str, pkg: &str| -> Result<String> {
        let pkg_mod = rust_ident(
            &format!("{}_{}", snake_case(ns), snake_case(pkg)),
            "dependency package module",
        )?;
        Ok(format!("super::super::{pkg_mod}"))
    };
    emit_dep_group(
        &mut out,
        0,
        "witforge_deps",
        &shared_slice,
        &shared_slice,
        serde,
        &shared_resolver,
        None,
    )?;

    for (&major, scoped_deps) in &layout.per_major {
        let major_mod = format!("v{major}");
        writeln!(out)?;
        writeln!(
            out,
            "/// Pinned dependencies for major version `{major_mod}`."
        )?;
        writeln!(out, "pub mod {major_mod} {{")?;
        let major_all = layout
            .by_major
            .get(&major)
            .map_or(scoped_deps.as_slice(), Vec::as_slice);
        let major_resolver = |ns: &str, pkg: &str| -> Result<String> {
            let pkg_mod = rust_ident(
                &format!("{}_{}", snake_case(ns), snake_case(pkg)),
                "dependency package module",
            )?;
            if layout.is_scoped(ns, pkg) {
                Ok(format!("super::super::{pkg_mod}"))
            } else {
                Ok(format!("super::super::super::{pkg_mod}"))
            }
        };
        emit_dep_group(
            &mut out,
            4,
            &major_mod,
            scoped_deps,
            major_all,
            serde,
            &major_resolver,
            Some((major, layout)),
        )?;
        writeln!(out, "}}")?;
    }
    Ok(out)
}

#[allow(clippy::too_many_arguments)]
fn emit_dep_group(
    out: &mut String,
    indent: usize,
    parent_mod: &str,
    emitted: &[crate::model::Dependency],
    all_in_scope: &[crate::model::Dependency],
    serde: bool,
    foreign_resolver: &dyn Fn(&str, &str) -> Result<String>,
    scoped_context: Option<(u64, &DepLayout)>,
) -> Result<()> {
    let prefix = " ".repeat(indent);
    let iface_prefix = " ".repeat(indent + 4);
    let mut module_names = BTreeMap::new();
    for (dep_idx, dependency) in emitted.iter().enumerate() {
        let module = rust_ident(
            &format!(
                "{}_{}",
                snake_case(&dependency.package.namespace),
                snake_case(&dependency.package.name)
            ),
            "dependency package module",
        )?;
        if let Some(previous) = module_names.insert(module.clone(), dependency.package.name.clone())
        {
            contract_bail!(
                "dependency packages `{previous}` and `{}` both map to Rust module `{module}`",
                dependency.package.name
            );
        }
        if indent == 0 || dep_idx > 0 {
            writeln!(out)?;
        }
        if let Some((major, layout)) = scoped_context {
            let owner = layout.canonical_owner_major(
                major,
                &dependency.package.namespace,
                &dependency.package.name,
            );
            if owner < major {
                writeln!(out, "{prefix}pub use super::v{owner}::{module};")?;
                continue;
            }
        }
        rustfmt::write_docs_or(
            out,
            indent,
            &dependency.package.docs,
            &format!(
                "Dependency package `{}:{}`.",
                dependency.package.namespace, dependency.package.name
            ),
        )?;
        if module == parent_mod {
            writeln!(out, "{prefix}#[allow(clippy::module_inception)]")?;
        }
        if dependency.interfaces.is_empty() {
            writeln!(out, "{prefix}pub mod {module} {{}}")?;
            continue;
        }
        writeln!(out, "{prefix}pub mod {module} {{")?;
        let dep_model = dependency_model(dependency, all_in_scope);
        for (idx, interface) in dependency.interfaces.iter().enumerate() {
            if idx > 0 {
                writeln!(out)?;
            }
            let interface_module =
                rust_ident(&snake_case(&interface.name), "dependency interface module")?;
            rustfmt::write_docs_or(
                out,
                indent + 4,
                &interface.docs,
                &format!(
                    "Interface `{}:{}/{}`.",
                    dependency.package.namespace, dependency.package.name, interface.name
                ),
            )?;
            if interface_module == module {
                writeln!(out, "{iface_prefix}#[allow(clippy::module_inception)]")?;
            }
            if interface.types.is_empty() && interface.functions.is_empty() {
                writeln!(out, "{iface_prefix}pub mod {interface_module} {{}}")?;
            } else {
                writeln!(out, "{iface_prefix}pub mod {interface_module} {{")?;
                emit_interface(
                    out,
                    indent + 8,
                    &dep_model,
                    interface,
                    serde,
                    foreign_resolver,
                )?;
                writeln!(out, "{iface_prefix}}}")?;
            }
        }
        writeln!(out, "{prefix}}}")?;
    }
    Ok(())
}

fn dependency_model(
    dependency: &crate::model::Dependency,
    dependencies: &[crate::model::Dependency],
) -> Model {
    Model {
        package: dependency.package.clone(),
        interfaces: dependency.interfaces.clone(),
        worlds: Vec::new(),
        dependencies: dependencies
            .iter()
            .filter(|other| {
                other.package.namespace != dependency.package.namespace
                    || other.package.name != dependency.package.name
            })
            .cloned()
            .collect(),
    }
}

fn write_derives(out: &mut String, indent: usize, serde: bool) -> Result<()> {
    let prefix = " ".repeat(indent);
    if serde {
        writeln!(
            out,
            "{prefix}#[derive(Debug, Clone, PartialEq, ::serde::Serialize, ::serde::Deserialize)]"
        )?;
    } else {
        writeln!(out, "{prefix}#[derive(Debug, Clone, PartialEq)]")?;
    }
    Ok(())
}

#[allow(clippy::too_many_arguments)]
fn emit_record(
    out: &mut String,
    indent: usize,
    model: &Model,
    interface: &crate::model::Interface,
    def: &TypeDef,
    name: &str,
    fields: &[crate::model::Field],
    serde: bool,
    foreign_resolver: &dyn Fn(&str, &str) -> Result<String>,
) -> Result<()> {
    let prefix = " ".repeat(indent);
    write_derives(out, indent, serde)?;
    if fields.is_empty() {
        writeln!(out, "{prefix}pub struct {name} {{}}")?;
        return Ok(());
    }
    writeln!(out, "{prefix}pub struct {name} {{")?;
    let mut field_names = BTreeMap::new();
    for field in fields {
        let field_name = rust_ident(&snake_case(&field.name), "record field")?;
        insert_name(
            &mut field_names,
            &field_name,
            &format!("field {}", field.name),
            &format!("{}/{}", interface.name, def.name),
        )?;
        rustfmt::write_docs_or(
            out,
            indent + 4,
            &field.docs,
            &format!("Field `{}/{}.{}`.", interface.name, def.name, field.name),
        )?;
        let ty = map_type(model, &interface.name, &field.ty, foreign_resolver)?;
        writeln!(
            out,
            "{}",
            rustfmt::fmt_struct_field(indent + 4, &field_name, &ty)
        )?;
    }
    writeln!(out, "{prefix}}}")?;
    Ok(())
}

#[allow(clippy::too_many_lines)]
fn emit_type_def(
    out: &mut String,
    indent: usize,
    model: &Model,
    interface: &crate::model::Interface,
    def: &TypeDef,
    serde: bool,
    foreign_resolver: &dyn Fn(&str, &str) -> Result<String>,
) -> Result<()> {
    let prefix = " ".repeat(indent);
    let member_prefix = " ".repeat(indent + 4);
    let name = rust_ident(&pascal_case(&def.name), "type")?;
    let fallback_doc = match &def.kind {
        TypeDefKind::Record(_) => format!("Record `{}/{}`.", interface.name, def.name),
        TypeDefKind::Variant(_) => format!("Variant `{}/{}`.", interface.name, def.name),
        TypeDefKind::Enum(_) => format!("Enum `{}/{}`.", interface.name, def.name),
        TypeDefKind::Flags(_) => format!("Flags `{}/{}`.", interface.name, def.name),
        TypeDefKind::Alias(_)
        | TypeDefKind::List(_)
        | TypeDefKind::Option(_)
        | TypeDefKind::Result(_) => format!("Type alias `{}/{}`.", interface.name, def.name),
    };
    rustfmt::write_docs_or(out, indent, &def.docs, &fallback_doc)?;
    match &def.kind {
        TypeDefKind::Record(fields) => {
            emit_record(
                out,
                indent,
                model,
                interface,
                def,
                &name,
                fields,
                serde,
                foreign_resolver,
            )?;
        }
        TypeDefKind::Variant(cases) => {
            write_derives(out, indent, serde)?;
            if has_large_variant_disparity(model, cases) {
                writeln!(out, "{prefix}#[allow(clippy::large_enum_variant)]")?;
            }
            if cases.is_empty() {
                writeln!(out, "{prefix}pub enum {name} {{}}")?;
                return Ok(());
            }
            writeln!(out, "{prefix}pub enum {name} {{")?;
            let mut case_names = BTreeMap::new();
            for case in cases {
                let case_name = rust_ident(&pascal_case(&case.name), "variant case")?;
                insert_name(
                    &mut case_names,
                    &case_name,
                    &format!("case {}", case.name),
                    &format!("{}/{}", interface.name, def.name),
                )?;
                rustfmt::write_docs_or(
                    out,
                    indent + 4,
                    &case.docs,
                    &format!("Case `{}/{}.{}`.", interface.name, def.name, case.name),
                )?;
                if let Some(payload) = &case.payload {
                    let ty = map_type(model, &interface.name, payload, foreign_resolver)?;
                    writeln!(
                        out,
                        "{}",
                        rustfmt::fmt_tuple_variant(indent + 4, &case_name, &ty)
                    )?;
                } else {
                    writeln!(out, "{member_prefix}{case_name},")?;
                }
            }
            writeln!(out, "{prefix}}}")?;
        }
        TypeDefKind::Enum(cases) => {
            write_derives(out, indent, serde)?;
            if cases.is_empty() {
                writeln!(out, "{prefix}pub enum {name} {{}}")?;
                return Ok(());
            }
            writeln!(out, "{prefix}pub enum {name} {{")?;
            let mut case_names = BTreeMap::new();
            for case in cases {
                let case_name = rust_ident(&pascal_case(&case.name), "enum case")?;
                insert_name(
                    &mut case_names,
                    &case_name,
                    &format!("case {}", case.name),
                    &format!("{}/{}", interface.name, def.name),
                )?;
                rustfmt::write_docs_or(
                    out,
                    indent + 4,
                    &case.docs,
                    &format!("Case `{}/{}.{}`.", interface.name, def.name, case.name),
                )?;
                writeln!(out, "{member_prefix}{case_name},")?;
            }
            writeln!(out, "{prefix}}}")?;
        }
        TypeDefKind::Flags(flags) => {
            write_derives(out, indent, serde)?;
            if flags.is_empty() {
                writeln!(out, "{prefix}pub struct {name} {{}}")?;
                return Ok(());
            }
            writeln!(out, "{prefix}pub struct {name} {{")?;
            let mut flag_names = BTreeMap::new();
            for flag in flags {
                let flag_name = rust_ident(&snake_case(&flag.name), "flag")?;
                insert_name(
                    &mut flag_names,
                    &flag_name,
                    &format!("flag {}", flag.name),
                    &format!("{}/{}", interface.name, def.name),
                )?;
                rustfmt::write_docs_or(
                    out,
                    indent + 4,
                    &flag.docs,
                    &format!("Flag `{}/{}.{}`.", interface.name, def.name, flag.name),
                )?;
                writeln!(out, "{member_prefix}pub {flag_name}: bool,")?;
            }
            writeln!(out, "{prefix}}}")?;
        }
        TypeDefKind::Alias(target) => {
            let ty = map_type(model, &interface.name, target, foreign_resolver)?;
            writeln!(
                out,
                "{}",
                rustfmt::fmt_type_alias(indent, &format!("pub type {name}"), &ty)
            )?;
        }
        TypeDefKind::List(element) => {
            let ty = if model.resolves_to_u8(element) {
                "::std::vec::Vec<u8>".to_string()
            } else {
                format!(
                    "::std::vec::Vec<{}>",
                    map_type(model, &interface.name, element, foreign_resolver)?
                )
            };
            writeln!(
                out,
                "{}",
                rustfmt::fmt_type_alias(indent, &format!("pub type {name}"), &ty)
            )?;
        }
        TypeDefKind::Option(payload) => {
            let ty = format!(
                "::std::option::Option<{}>",
                map_type(model, &interface.name, payload, foreign_resolver)?
            );
            writeln!(
                out,
                "{}",
                rustfmt::fmt_type_alias(indent, &format!("pub type {name}"), &ty)
            )?;
        }
        TypeDefKind::Result(result) => {
            let ok = result.ok.as_ref().map_or_else(
                || Ok("()".to_string()),
                |ty| map_type(model, &interface.name, ty, foreign_resolver),
            )?;
            let err = result.err.as_ref().map_or_else(
                || Ok("()".to_string()),
                |ty| map_type(model, &interface.name, ty, foreign_resolver),
            )?;
            let ty = format!("::std::result::Result<{ok}, {err}>");
            writeln!(
                out,
                "{}",
                rustfmt::fmt_type_alias(indent, &format!("pub type {name}"), &ty)
            )?;
        }
    }
    Ok(())
}

fn emit_trait(
    out: &mut String,
    indent: usize,
    model: &Model,
    interface: &crate::model::Interface,
    trait_name: &str,
    foreign_resolver: &dyn Fn(&str, &str) -> Result<String>,
) -> Result<()> {
    let prefix = " ".repeat(indent);
    writeln!(out, "{prefix}/// Trait for interface `{}`.", interface.name)?;
    writeln!(out, "{prefix}pub trait {trait_name} {{")?;
    let mut function_names = BTreeMap::new();
    for (idx, function) in interface.functions.iter().enumerate() {
        if idx > 0 {
            writeln!(out)?;
        }
        let name = rust_ident(&snake_case(&function.name), "function")?;
        insert_name(
            &mut function_names,
            &name,
            &format!("function {}", function.name),
            &format!("trait {}", interface.name),
        )?;
        rustfmt::write_docs_or(
            out,
            indent + 4,
            &function.docs,
            &format!("Function `{}#{}`.", interface.name, function.name),
        )?;
        let mut params = vec!["&self".to_string()];
        let mut param_names = BTreeMap::new();
        for param in &function.params {
            let param_name = rust_ident(&snake_case(&param.name), "parameter")?;
            insert_name(
                &mut param_names,
                &param_name,
                &format!("parameter {}", param.name),
                &format!("function {}/{}", interface.name, function.name),
            )?;
            let ty = map_type(model, &interface.name, &param.ty, foreign_resolver)?;
            params.push(format!("{param_name}: {ty}"));
        }
        let ret = function
            .result
            .as_ref()
            .map(|result| map_type(model, &interface.name, result, foreign_resolver))
            .transpose()?;
        let method_prefix = " ".repeat(indent + 4);
        if params.len() > 7 {
            writeln!(out, "{method_prefix}#[allow(clippy::too_many_arguments)]")?;
        }
        if function
            .result
            .as_ref()
            .is_some_and(|result| resolves_to_unit_err_result(model, result))
        {
            writeln!(out, "{method_prefix}#[allow(clippy::result_unit_err)]")?;
        }
        writeln!(
            out,
            "{}",
            rustfmt::fmt_fn_sig(
                indent + 4,
                &format!("fn {name}"),
                &params,
                ret.as_deref(),
                ";"
            )
        )?;
    }
    writeln!(out, "{prefix}}}")?;
    Ok(())
}

fn resolves_to_unit_err_result(model: &Model, ty: &TypeExpr) -> bool {
    let mut current = ty;
    for _ in 0..=crate::model::MAX_ALIAS_CHAIN {
        match current {
            TypeExpr::Result(result) => return result.err.is_none(),
            TypeExpr::Named(name) => {
                let Some(def) = model.type_def(name) else {
                    return false;
                };
                match &def.kind {
                    TypeDefKind::Result(result) => return result.err.is_none(),
                    TypeDefKind::Alias(target) => current = target,
                    _ => return false,
                }
            }
            _ => return false,
        }
    }
    false
}

/// Conservative 64-bit size estimate for `clippy::large_enum_variant` (default threshold 200 bytes).
/// Emits `#[allow(clippy::large_enum_variant)]` only when a variant's largest and second-largest
/// cases differ by at least 160 estimated bytes.
fn has_large_variant_disparity(model: &Model, cases: &[crate::model::Case]) -> bool {
    if cases.len() < 2 {
        return false;
    }
    let mut sizes: Vec<usize> = cases
        .iter()
        .map(|case| {
            case.payload
                .as_ref()
                .map_or(0, |ty| estimate_type_size(model, ty, 0))
        })
        .collect();
    sizes.sort_unstable();
    let largest = sizes[sizes.len() - 1];
    let second = sizes[sizes.len() - 2];
    largest.saturating_sub(second) >= 160
}

fn estimate_type_size(model: &Model, ty: &TypeExpr, depth: usize) -> usize {
    if depth > crate::model::MAX_TYPE_NESTING {
        return 24;
    }
    match ty {
        TypeExpr::Bool | TypeExpr::U8 | TypeExpr::S8 => 1,
        TypeExpr::U16 | TypeExpr::S16 => 2,
        TypeExpr::U32 | TypeExpr::S32 | TypeExpr::F32 => 4,
        TypeExpr::U64 | TypeExpr::S64 | TypeExpr::F64 => 8,
        TypeExpr::String | TypeExpr::List(_) => 24,
        TypeExpr::Option(inner) => estimate_type_size(model, inner, depth + 1).saturating_add(8),
        TypeExpr::Result(result) => {
            let ok = result
                .ok
                .as_deref()
                .map_or(0, |t| estimate_type_size(model, t, depth + 1));
            let err = result
                .err
                .as_deref()
                .map_or(0, |t| estimate_type_size(model, t, depth + 1));
            ok.max(err).saturating_add(8)
        }
        TypeExpr::Named(name) => {
            let Some(def) = model.type_def(name) else {
                return 8;
            };
            match &def.kind {
                TypeDefKind::Record(fields) => fields.iter().fold(0usize, |acc, field| {
                    let fsz = estimate_type_size(model, &field.ty, depth + 1);
                    // Round up each field to at most 8-byte alignment for a safe upper bound.
                    acc.saturating_add(fsz.next_multiple_of(fsz.clamp(1, 8)))
                }),
                TypeDefKind::Variant(cases) => cases
                    .iter()
                    .map(|case| {
                        case.payload
                            .as_ref()
                            .map_or(0, |t| estimate_type_size(model, t, depth + 1))
                    })
                    .max()
                    .unwrap_or(0)
                    .saturating_add(8),
                TypeDefKind::Enum(_) => 4,
                TypeDefKind::Flags(flags) => flags.len(),
                TypeDefKind::Alias(target) => estimate_type_size(model, target, depth + 1),
                TypeDefKind::List(_) => 24,
                TypeDefKind::Option(inner) => {
                    estimate_type_size(model, inner, depth + 1).saturating_add(8)
                }
                TypeDefKind::Result(result) => {
                    let ok = result
                        .ok
                        .as_deref()
                        .map_or(0, |t| estimate_type_size(model, t, depth + 1));
                    let err = result
                        .err
                        .as_deref()
                        .map_or(0, |t| estimate_type_size(model, t, depth + 1));
                    ok.max(err).saturating_add(8)
                }
            }
        }
    }
}

fn map_type(
    model: &Model,
    current_interface: &str,
    ty: &TypeExpr,
    foreign_resolver: &dyn Fn(&str, &str) -> Result<String>,
) -> Result<String> {
    match ty {
        TypeExpr::Bool => Ok("bool".to_string()),
        TypeExpr::U8 => Ok("u8".to_string()),
        TypeExpr::U16 => Ok("u16".to_string()),
        TypeExpr::U32 => Ok("u32".to_string()),
        TypeExpr::U64 => Ok("u64".to_string()),
        TypeExpr::S8 => Ok("i8".to_string()),
        TypeExpr::S16 => Ok("i16".to_string()),
        TypeExpr::S32 => Ok("i32".to_string()),
        TypeExpr::S64 => Ok("i64".to_string()),
        TypeExpr::F32 => Ok("f32".to_string()),
        TypeExpr::F64 => Ok("f64".to_string()),
        TypeExpr::String => Ok("::std::string::String".to_string()),
        TypeExpr::Named(name) => {
            if let Some((namespace, package)) = name.package() {
                let package_path = foreign_resolver(namespace, package)?;
                let interface = rust_ident(
                    &snake_case(name.interface_name()),
                    "dependency interface module",
                )?;
                let type_name = rust_ident(&pascal_case(&name.name), "type")?;
                return Ok(format!("{package_path}::{interface}::{type_name}"));
            }
            model.type_def(name).with_context(|| {
                format!(
                    "named type `{}/{}` is not in the model",
                    name.interface, name.name
                )
            })?;
            let type_name = rust_ident(&pascal_case(&name.name), "type")?;
            if name.interface == current_interface {
                Ok(type_name)
            } else {
                let module = rust_ident(&snake_case(&name.interface), "interface module")?;
                Ok(format!("super::{module}::{type_name}"))
            }
        }
        TypeExpr::List(element) => {
            if model.resolves_to_u8(element) {
                Ok("::std::vec::Vec<u8>".to_string())
            } else {
                Ok(format!(
                    "::std::vec::Vec<{}>",
                    map_type(model, current_interface, element, foreign_resolver)?
                ))
            }
        }
        TypeExpr::Option(payload) => Ok(format!(
            "::std::option::Option<{}>",
            map_type(model, current_interface, payload, foreign_resolver)?
        )),
        TypeExpr::Result(result) => {
            let ok = result.ok.as_ref().map_or_else(
                || Ok("()".to_string()),
                |ty| map_type(model, current_interface, ty, foreign_resolver),
            )?;
            let err = result.err.as_ref().map_or_else(
                || Ok("()".to_string()),
                |ty| map_type(model, current_interface, ty, foreign_resolver),
            )?;
            Ok(format!("::std::result::Result<{ok}, {err}>"))
        }
    }
}

/// Emit the additive shared world metadata for every version.
///
/// Worlds are not traits: the metadata records each world's name and its imported and exported
/// interface names in source order. Each version gets its own `WORLDS` constant, so adding a
/// version changes only this shared file; per-version Rust modules stay frozen.
fn emit_worlds(versions: &[Version]) -> Result<String> {
    let Some(first) = versions.first() else {
        bail!("no version directories found under WIT root");
    };
    let mut out = String::new();
    writeln!(
        out,
        "{}",
        header_for(&first.model.package.namespace, &first.model.package.name)
    )?;
    writeln!(
        out,
        "// source: {}:{}",
        first.model.package.namespace, first.model.package.name
    )?;
    writeln!(out)?;
    writeln!(
        out,
        "/// One contract world and the interfaces it imports and exports."
    )?;
    writeln!(out, "pub struct World {{")?;
    writeln!(out, "    /// The WIT world name.")?;
    writeln!(out, "    pub name: &'static str,")?;
    writeln!(out, "    /// Imported interface names, in source order.")?;
    writeln!(out, "    pub imports: &'static [&'static str],")?;
    writeln!(out, "    /// Exported interface names, in source order.")?;
    writeln!(out, "    pub exports: &'static [&'static str],")?;
    writeln!(out, "}}")?;
    for version in versions {
        let module = version_module_name(&version.model);
        writeln!(out)?;
        writeln!(out, "/// World metadata for `{module}`.")?;
        writeln!(out, "pub mod {module} {{")?;
        writeln!(
            out,
            "    /// The worlds of {}.",
            version.model.package.version
        )?;
        for world in &version.model.worlds {
            let world_lines = docs::sanitize_rust_lines(&world.docs);
            if !world_lines.is_empty() {
                writeln!(out, "    ///")?;
                writeln!(out, "    /// World `{}`:", world.name)?;
                writeln!(out, "    ///")?;
                for line in world_lines {
                    if line.is_empty() {
                        writeln!(out, "    ///")?;
                    } else {
                        writeln!(out, "    /// {line}")?;
                    }
                }
            }
        }
        match version.model.worlds.as_slice() {
            [] => {
                writeln!(out, "    pub const WORLDS: &[super::World] = &[];")?;
            }
            [world] => {
                writeln!(
                    out,
                    "    pub const WORLDS: &[super::World] = &[super::World {{"
                )?;
                write_world_fields(&mut out, 8, world)?;
                writeln!(out, "    }}];")?;
            }
            worlds => {
                writeln!(out, "    pub const WORLDS: &[super::World] = &[")?;
                for world in worlds {
                    writeln!(out, "        super::World {{")?;
                    write_world_fields(&mut out, 12, world)?;
                    writeln!(out, "        }},")?;
                }
                writeln!(out, "    ];")?;
            }
        }
        writeln!(out, "}}")?;
    }
    Ok(out)
}

fn write_world_fields(out: &mut String, indent: usize, world: &crate::model::World) -> Result<()> {
    let prefix = " ".repeat(indent);
    writeln!(out, "{prefix}name: {:?},", world.name)?;
    let imports: Vec<String> = world
        .imports
        .iter()
        .map(|interface| format!("{:?}", interface.qualified_name()))
        .collect();
    let imports_rendered =
        rustfmt::fmt_string_slice(indent, &imports, indent + "imports: ".len(), 1);
    writeln!(out, "{prefix}imports: {imports_rendered},")?;
    let exports: Vec<String> = world
        .exports
        .iter()
        .map(|interface| format!("{:?}", interface.qualified_name()))
        .collect();
    let exports_rendered =
        rustfmt::fmt_string_slice(indent, &exports, indent + "exports: ".len(), 1);
    writeln!(out, "{prefix}exports: {exports_rendered},")?;
    Ok(())
}

fn insert_name(
    names: &mut BTreeMap<String, String>,
    ident: &str,
    source: &str,
    scope: &str,
) -> Result<()> {
    if let Some(previous) = names.insert(ident.to_string(), source.to_string()) {
        contract_bail!(
            "{scope}: Rust name `{ident}` is produced by both `{previous}` and `{source}`"
        );
    }
    Ok(())
}
